function M.extension()
  return { exports = { open = M.picker } }
end

function M.where(lk)
  if lk.file then return ("%s:%d"):format(vim.fn.fnamemodify(lk.file, ":t"), lk.lnum) end
  return ("buf:%d"):format(lk.lnum)
end

function M.rows(links)
  local rows = {}
  for i, lk in ipairs(links) do
    rows[i] = { lk.kind, M.where(lk), lk.text or "", lk.target }
  end
  return { "Kind", "Location", "Text", "Target" }, rows
end

local function trim(s)
  return (s:gsub("^%s*(.-)%s*$", "%1"))
end

local function strip_trailing_punct(s)
  return (s:gsub("[%.,;:%)%]%}>!%?]+$", ""))
end

function M.is_anchor(target)
  return target ~= nil and target:match("^#") ~= nil
end

local function expand(p)
  return require("lib.nvim.cross.fs.expand_path")(p)
end

local function resolve_tmux_conf()
  return first_existing({
    expand("~/.config/tmux/tmux.conf"),
    expand("~/.tmux.conf"),
  })
end

local function resolve_wezterm_conf()
  return first_existing({
    expand("~/.config/wezterm/wezterm.lua"),
    expand("~/.wezterm.lua"),
  })
end

local function resolve_docker_config()
  return expand("~/.docker/config.json")
end

function M.setup(cfg)
  vim.api.nvim_create_augroup(AUGROUP, { clear = true })

  if not cfg or not cfg.enabled then return end
  local extensions = cfg.extensions or {}
  if #extensions == 0 then return end

  vim.api.nvim_create_autocmd("BufReadCmd", {
    group = AUGROUP,
    pattern = build_pattern(extensions),
    desc = "open.nvim: redirect MS Office documents to the system app",
    callback = on_read,
  })
end

function M.get()
  if _cache then return _cache end

  _cache = {
    is_win = is_windows(),
    is_mac = is_macos(),
    is_wsl = is_wsl(),
    is_linux = is_linux(),
  }

  return _cache
end

function M.list()
  local result = {}
  for _, h in pairs(_handlers) do
    result[#result + 1] = h
  end
  table.sort(result, function(a, b)
    return a.key < b.key
  end)
  return result
end

function M.url_encode(s)
  s = tostring(s)
  s = s:gsub("([^%w%-%.%_%~ ])", function(c)
    return string.format("%%%02X", string.byte(c))
  end)
  local encoded = s:gsub(" ", "+")
  return encoded
end

function M.cmd_escape_unquoted(s)
  return (s:gsub("([&|<>^])", "^%1"))
end
